from taf.ul.kpi_selector.operations.factory_prototype.classical_factory_prototype import OperationFactoryPrototype
from taf.ul.kpi_selector.operations.sw_activation.classical_sw_activation.sw_activation_22R1 import SwActivation22R1
from taf.ul.kpi_selector.operations.sw_activation.classical_sw_activation.sw_activation_22R2 import SwActivation22R2
from taf.ul.kpi_selector.operations.sw_activation.classical_sw_activation.sw_activation_22R3 import SwActivation22R3
from taf.ul.kpi_selector.operations.sw_activation.classical_sw_activation.sw_activation_23R1 import SwActivation23R1


class SwActivationFactory(OperationFactoryPrototype):
    def __init__(self):
        super(SwActivationFactory, self).__init__()

    def bts_setter(self, bts):
        """
        Hands over Bts instance for given testline.
        :param bts: Bts instance
        :type bts: Bts instance from /taf/ul/kpi_selector/BTSs
        """
        self.bts = bts

    def get_kpi(self, inter_release=False):
        """
        Gets kpi for software activation operation.
        :param inter_release: boolean value whether activated sw is of different stream than the one active on BTS;
                              defaults to False
        :type inter_release: bool
        :return: dictionary with timeout, requirement and operation description for software activation
        :rtype: dict
        """

        if self.bts.stream == "SBTS22R1":
            return SwActivation22R1(self.bts).get_kpi(inter_release=inter_release)

        elif self.bts.stream == "SBTS22R2":
            return SwActivation22R2(self.bts).get_kpi(inter_release=inter_release)

        elif self.bts.stream == "SBTS22R3" or self.bts.stream == "SBTS22R4":
            return SwActivation22R3(self.bts).get_kpi(inter_release=inter_release)

        elif self.bts.stream >= "SBTS23R1":
            return SwActivation23R1(self.bts).get_kpi(inter_release=inter_release)
